MATCH (g:Gene)-[r1:GENEINPATHWAY]->(p1:Pathway {commonName: "TNFalpha"}), (g)-[r2:GENEINPATHWAY]->(p2:Pathway {commonName: "RIG-I-like receptor signaling pathway - Homo sapiens (human)"})
WHERE g.geneSymbol IN ["MAPK8", "TRAF6", "CHUK", "MAPK14", "LOC127401194"]
RETURN g, r1, p1, r2, p2;

MATCH (sym:Symptom)
WHERE sym.commonName IN ["Hypokinesia", "Aphasia, Wernicke", "Apraxias", "Confusion", "Myoclonus"]
  AND NOT (
    EXISTS { MATCH (sym)-[:SYMPTOMMANIFESTATIONOFDISEASE]->(:Disease {commonName: "Alzheimer's Disease"}) }
    AND
    EXISTS { MATCH (sym)-[:SYMPTOMMANIFESTATIONOFDISEASE]->(:Disease {commonName: "Familial Alzheimer Disease (FAD)"}) }
  )
RETURN sym
